using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;

            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }

        public static SchoolContext CreateSeeded(string dbName = null)
        {
            var context = Create(dbName);
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000,
                StartDate = DateTime.Parse("2007-09-01")
            };
            context.Departments.Add(dept);

            var dept2 = new Department
            {
                DepartmentID = 2,
                Name = "Mathematics",
                Budget = 100000,
                StartDate = DateTime.Parse("2007-09-01")
            };
            context.Departments.Add(dept2);
            context.SaveChanges();

            var instructor = new Instructor
            {
                ID = 1,
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = DateTime.Parse("1995-03-11"),
                CourseAssignments = new List<CourseAssignment>(),
            };
            context.Instructors.Add(instructor);

            var instructor2 = new Instructor
            {
                ID = 2,
                FirstMidName = "Fadi",
                LastName = "Fakhouri",
                HireDate = DateTime.Parse("2002-07-06"),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { Location = "Smith 17" }
            };
            context.Instructors.Add(instructor2);
            context.SaveChanges();

            var course1 = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1
            };
            context.Courses.Add(course1);

            var course2 = new Course
            {
                CourseID = 1045,
                Title = "Calculus",
                Credits = 4,
                DepartmentID = 2
            };
            context.Courses.Add(course2);
            context.SaveChanges();

            context.CourseAssignments.Add(new CourseAssignment { CourseID = 1050, InstructorID = 1 });
            context.SaveChanges();

            var student1 = new Student
            {
                ID = 10,
                FirstMidName = "Carson",
                LastName = "Alexander",
                EnrollmentDate = DateTime.Parse("2010-09-01")
            };
            context.Students.Add(student1);

            var student2 = new Student
            {
                ID = 11,
                FirstMidName = "Meredith",
                LastName = "Alonso",
                EnrollmentDate = DateTime.Parse("2012-09-01")
            };
            context.Students.Add(student2);

            var student3 = new Student
            {
                ID = 12,
                FirstMidName = "Arturo",
                LastName = "Anand",
                EnrollmentDate = DateTime.Parse("2013-09-01")
            };
            context.Students.Add(student3);
            context.SaveChanges();

            context.Enrollments.Add(new Enrollment
            {
                StudentID = 10,
                CourseID = 1050,
                Grade = Grade.A
            });
            context.Enrollments.Add(new Enrollment
            {
                StudentID = 11,
                CourseID = 1045,
                Grade = Grade.B
            });
            context.SaveChanges();
        }
    }
}

