using ContosoUniversity.Models;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        [Fact]
        public void FullName_ReturnsCombinedLastAndFirst()
        {
            var student = new Student
            {
                FirstMidName = "John",
                LastName = "Doe"
            };

            Assert.Equal("Doe, John", student.FullName);
        }

        [Fact]
        public void FullName_WorksForInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Jane",
                LastName = "Smith"
            };

            Assert.Equal("Smith, Jane", instructor.FullName);
        }
    }

    public class ErrorViewModelTests
    {
        [Fact]
        public void ShowRequestId_TrueWhenRequestIdIsSet()
        {
            var model = new ErrorViewModel { RequestId = "abc123" };

            Assert.True(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_FalseWhenRequestIdIsNull()
        {
            var model = new ErrorViewModel { RequestId = null };

            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_FalseWhenRequestIdIsEmpty()
        {
            var model = new ErrorViewModel { RequestId = "" };

            Assert.False(model.ShowRequestId);
        }
    }

    public class StudentModelTests
    {
        [Fact]
        public void Student_InheritsFromPerson()
        {
            var student = new Student();
            Assert.IsAssignableFrom<Person>(student);
        }

        [Fact]
        public void Student_HasEnrollmentDate()
        {
            var date = DateTime.Parse("2020-09-01");
            var student = new Student { EnrollmentDate = date };

            Assert.Equal(date, student.EnrollmentDate);
        }

        [Fact]
        public void Student_HasEnrollmentsCollection()
        {
            var student = new Student
            {
                Enrollments = new List<Enrollment>
                {
                    new Enrollment { EnrollmentID = 1 },
                    new Enrollment { EnrollmentID = 2 }
                }
            };

            Assert.Equal(2, student.Enrollments.Count);
        }
    }

    public class InstructorModelTests
    {
        [Fact]
        public void Instructor_InheritsFromPerson()
