        public void CanAddCourseWithDepartment()
        {
            var dept = new Department
            {
                Name = "Science",
                Budget = 100000,
                StartDate = DateTime.Now
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 5000,
                Title = "Physics",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var retrieved = _context.Courses
                .Include(c => c.Department)
                .First(c => c.CourseID == 5000);
            Assert.Equal("Physics", retrieved.Title);
            Assert.Equal("Science", retrieved.Department.Name);
        }

        [Fact]
        public void CanAddEnrollment()
        {
            var student = new Student
            {
                FirstMidName = "Enroll",
                LastName = "Test",
                EnrollmentDate = DateTime.Parse("2020-09-01")
            };
            _context.Students.Add(student);

            var dept = new Department
            {
                Name = "EnrollDept",
                Budget = 50000,
                StartDate = DateTime.Now
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 6000,
                Title = "EnrollCourse",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var enrollment = new Enrollment
            {
                StudentID = student.ID,
                CourseID = 6000,
                Grade = Grade.A
            };
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            var retrieved = _context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .First(e => e.CourseID == 6000);
            Assert.Equal(Grade.A, retrieved.Grade);
            Assert.Equal("Test", retrieved.Student.LastName);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            var instructor = new Instructor
            {
                FirstMidName = "CA",
                LastName = "Test",
                HireDate = DateTime.Parse("2020-01-01")
            };
            _context.Instructors.Add(instructor);

            var dept = new Department
            {
                Name = "CADept",
                Budget = 50000,
                StartDate = DateTime.Now
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 7000,
                Title = "CATest",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var assignment = new CourseAssignment
            {
                CourseID = 7000,
                InstructorID = instructor.ID
            };
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            var retrieved = _context.CourseAssignments
                .First(ca => ca.CourseID == 7000 && ca.InstructorID == instructor.ID);
            Assert.NotNull(retrieved);
        }

        [Fact]
        public void OfficeAssignment_OneToOneWithInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Office",
                LastName = "Test",
                HireDate = DateTime.Parse("2020-01-01"),
                OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var retrieved = _context.Instructors
                .Include(i => i.OfficeAssignment)
                .First(i => i.LastName == "Test" && i.FirstMidName == "Office");
            Assert.NotNull(retrieved.OfficeAssignment);
            Assert.Equal("Room 101", retrieved.OfficeAssignment.Location);
        }

        [Fact]
        public void CanAddNotification()
        {
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test notification",
                CreatedAt = DateTime.Now,
                CreatedBy = "Test",
                IsRead = false
            };
            _context.Notifications.Add(notification);
            _context.SaveChanges();

            var retrieved = _context.Notifications.First(n => n.Message == "Test notification");
            Assert.Equal("Student", retrieved.EntityType);
        }

        [Fact]
        public void People_DbSet_ContainsBothStudentsAndInstructors()
        {
            var student = new Student
            {
                FirstMidName = "Person",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2020-09-01")
            };
            var instructor = new Instructor
            {
                FirstMidName = "Person",
                LastName = "Instructor",
                HireDate = DateTime.Parse("2020-01-01")
            };

            _context.Students.Add(student);
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var people = _context.People.ToList();
            Assert.Contains(people, p => p.LastName == "Student");
            Assert.Contains(people, p => p.LastName == "Instructor");
        }
    }

