using ContosoUniversity.Models;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        [Fact]
        public void FullName_ReturnsCombinedLastAndFirst()
        {
            var student = new Student
            {
                FirstMidName = "John",
                LastName = "Doe"
            };

            Assert.Equal("Doe, John", student.FullName);
        }

        [Fact]
        public void FullName_WorksForInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Jane",
                LastName = "Smith"
            };

            Assert.Equal("Smith, Jane", instructor.FullName);
        }
    }

    public class ErrorViewModelTests
    {
        [Fact]
        public void ShowRequestId_TrueWhenRequestIdIsSet()
        {
            var model = new ErrorViewModel { RequestId = "abc123" };

            Assert.True(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_FalseWhenRequestIdIsNull()
        {
            var model = new ErrorViewModel { RequestId = null };

            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_FalseWhenRequestIdIsEmpty()
        {
            var model = new ErrorViewModel { RequestId = "" };

            Assert.False(model.ShowRequestId);
        }
    }

    public class StudentModelTests
    {
        [Fact]
        public void Student_InheritsFromPerson()
        {
            var student = new Student();
            Assert.IsAssignableFrom<Person>(student);
        }

        [Fact]
        public void Student_HasEnrollmentDate()
        {
            var date = DateTime.Parse("2020-09-01");
            var student = new Student { EnrollmentDate = date };

            Assert.Equal(date, student.EnrollmentDate);
        }

        [Fact]
        public void Student_HasEnrollmentsCollection()
        {
            var student = new Student
            {
                Enrollments = new List<Enrollment>
                {
                    new Enrollment { EnrollmentID = 1 },
                    new Enrollment { EnrollmentID = 2 }
                }
            };

            Assert.Equal(2, student.Enrollments.Count);
        }
    }

    public class InstructorModelTests
    {
        [Fact]
        public void Instructor_InheritsFromPerson()
        {
            var instructor = new Instructor();
            Assert.IsAssignableFrom<Person>(instructor);
        }

        [Fact]
        public void Instructor_HasHireDate()
        {
            var date = DateTime.Parse("2020-01-01");
            var instructor = new Instructor { HireDate = date };

            Assert.Equal(date, instructor.HireDate);
        }

        [Fact]
        public void Instructor_HasCourseAssignmentsCollection()
        {
            var instructor = new Instructor
            {
                CourseAssignments = new List<CourseAssignment>
                {
                    new CourseAssignment { CourseID = 1 }
                }
            };

            Assert.Single(instructor.CourseAssignments);
        }

        [Fact]
        public void Instructor_HasOfficeAssignment()
        {
            var instructor = new Instructor
            {
                OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
            };

            Assert.Equal("Room 101", instructor.OfficeAssignment.Location);
        }
    }

    public class CourseModelTests
    {
        [Fact]
        public void Course_Properties_SetCorrectly()
        {
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/uploads/test.jpg"
            };

            Assert.Equal(1050, course.CourseID);
            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Equal("/uploads/test.jpg", course.TeachingMaterialImagePath);
        }

        [Fact]
        public void Course_HasNavigationProperties()
        {
            var course = new Course
            {
                Department = new Department { Name = "TestDept" },
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };

            Assert.NotNull(course.Department);
            Assert.NotNull(course.Enrollments);
            Assert.NotNull(course.CourseAssignments);
        }
    }

    public class DepartmentModelTests
    {
        [Fact]
        public void Department_Properties_SetCorrectly()
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000,
                StartDate = DateTime.Parse("2007-09-01"),
                InstructorID = 5
            };

            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("Engineering", dept.Name);
            Assert.Equal(350000, dept.Budget);
            Assert.Equal(5, dept.InstructorID);
        }

        [Fact]
        public void Department_InstructorID_Nullable()
        {
            var dept = new Department { InstructorID = null };
            Assert.Null(dept.InstructorID);
        }

        [Fact]
        public void Department_HasNavigationProperties()
        {
            var dept = new Department
            {
                Administrator = new Instructor { LastName = "Admin" },
                Courses = new List<Course>()
            };

            Assert.NotNull(dept.Administrator);
            Assert.NotNull(dept.Courses);
        }
    }

    public class EnrollmentModelTests
    {
        [Fact]
        public void Enrollment_GradeIsNullable()
        {
            var enrollment = new Enrollment { Grade = null };
            Assert.Null(enrollment.Grade);
        }

        [Fact]
        public void Enrollment_GradeValues()
        {
            Assert.Equal(0, (int)Grade.A);
            Assert.Equal(1, (int)Grade.B);
            Assert.Equal(2, (int)Grade.C);
            Assert.Equal(3, (int)Grade.D);
            Assert.Equal(4, (int)Grade.F);
        }
    }

    public class NotificationModelTests
    {
        [Fact]
        public void Notification_Properties_SetCorrectly()
        {
            var now = DateTime.Now;
            var notification = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "10",
                Operation = "CREATE",
                Message = "New Student",
                CreatedAt = now,
                CreatedBy = "Admin",
                IsRead = false,
                ReadAt = null
            };

            Assert.Equal(1, notification.Id);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("10", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("New Student", notification.Message);
            Assert.Equal(now, notification.CreatedAt);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Null(notification.ReadAt);
        }

        [Fact]
        public void EntityOperation_HasExpectedValues()
        {
            Assert.Equal(0, (int)EntityOperation.CREATE);
            Assert.Equal(1, (int)EntityOperation.UPDATE);
            Assert.Equal(2, (int)EntityOperation.DELETE);
        }
    }

    public class PaginatedListTests
    {
        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            var source = Enumerable.Range(1, 50).AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(5, result.TotalPages);
        }

        [Fact]
        public void Create_SecondPage()
        {
            var source = Enumerable.Range(1, 50).AsQueryable();
            var result = PaginatedList<int>.Create(source, 2, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(11, result[0]);
        }

        [Fact]
        public void HasPreviousPage_FalseOnFirstPage()
        {
            var source = Enumerable.Range(1, 50).AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_TrueOnSecondPage()
        {
            var source = Enumerable.Range(1, 50).AsQueryable();
            var result = PaginatedList<int>.Create(source, 2, 10);

            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_TrueWhenNotLastPage()
        {
            var source = Enumerable.Range(1, 50).AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_FalseOnLastPage()
        {
            var source = Enumerable.Range(1, 50).AsQueryable();
            var result = PaginatedList<int>.Create(source, 5, 10);

            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void TotalPages_CalculatedCorrectly()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(3, result.TotalPages); // 25/10 = 2.5, ceiling = 3
        }

        [Fact]
        public void TotalPages_ExactDivision()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(2, result.TotalPages);
        }

        [Fact]
        public void Create_EmptySource()
        {
            var source = Enumerable.Empty<int>().AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }

        [Fact]
        public void Create_SinglePage()
        {
            var source = Enumerable.Range(1, 5).AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Constructor_AddsAllItems()
        {
            var items = new List<int> { 1, 2, 3 };
            var result = new PaginatedList<int>(items, 10, 2, 3);

            Assert.Equal(3, result.Count);
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(4, result.TotalPages); // ceiling(10/3) = 4
        }
    }
}

