using System;
using System.Collections.Generic;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain any leftover notifications from the static queue
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain to avoid polluting other tests
            while (_service.ReceiveNotification() != null) { }
            _service.Dispose();
        }

        private Notification DrainAndReceiveLast()
        {
            // After we send exactly one notification, drain until we get
            // the last one (ours), skipping any that arrived from parallel tests.
            Notification last = null;
            Notification n;
            while ((n = _service.ReceiveNotification()) != null)
            {
                last = n;
            }
            return last;
        }

        private List<Notification> DrainAll()
        {
            var list = new List<Notification>();
            Notification n;
            while ((n = _service.ReceiveNotification()) != null)
            {
                list.Add(n);
            }
            return list;
        }

        [Fact]
        public void SendNotification_EnqueuesNotification()
        {
            _service.SendNotification("TestEntity_Enqueue", "1", EntityOperation.CREATE);

            var all = DrainAll();
            var notification = all.Find(n => n.EntityType == "TestEntity_Enqueue");
            Assert.NotNull(notification);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
        }

        [Fact]
        public void SendNotification_WithDisplayName_GeneratesCorrectMessage()
        {
