            Assert.NotNull(notification);
            Assert.Contains("(ID: 42)", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_Delete_GeneratesDeleteMessage()
        {
            _service.SendNotification("TestEntity_Del", "5", "Physics", EntityOperation.DELETE);

            var all = DrainAll();
            var notification = all.Find(n => n.EntityType == "TestEntity_Del");
            Assert.NotNull(notification);
            Assert.Contains("deleted", notification.Message);
            Assert.Contains("Physics", notification.Message);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtAndCreatedBy()
        {
            _service.SendNotification("TestEntity_CreatedBy", "1", EntityOperation.CREATE, "TestUser");

            var all = DrainAll();
            var notification = all.Find(n => n.EntityType == "TestEntity_CreatedBy");
            Assert.NotNull(notification);
            Assert.Equal("TestUser", notification.CreatedBy);
            Assert.True((DateTime.Now - notification.CreatedAt).TotalSeconds < 5);
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            _service.SendNotification("TestEntity_NullUser", "1", EntityOperation.CREATE);

            var all = DrainAll();
            var notification = all.Find(n => n.EntityType == "TestEntity_NullUser");
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsIsReadToFalse()
        {
            _service.SendNotification("TestEntity_IsRead", "1", EntityOperation.CREATE);

            var all = DrainAll();
            var notification = all.Find(n => n.EntityType == "TestEntity_IsRead");
            Assert.NotNull(notification);
            Assert.False(notification.IsRead);
            Assert.Null(notification.ReadAt);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            // Drain everything first
            while (_service.ReceiveNotification() != null) { }

            var notification = _service.ReceiveNotification();
            Assert.Null(notification);
        }

        [Fact]
        public void ReceiveNotification_FIFO_Order()
        {
            _service.SendNotification("FIFO_First", "1", EntityOperation.CREATE);
            _service.SendNotification("FIFO_Second", "2", EntityOperation.UPDATE);

            var all = DrainAll();
            var firstIdx = all.FindIndex(n => n.EntityType == "FIFO_First");
            var secondIdx = all.FindIndex(n => n.EntityType == "FIFO_Second");
            Assert.True(firstIdx >= 0);
            Assert.True(secondIdx >= 0);
            Assert.True(firstIdx < secondIdx);
        }

        [Fact]
        public void ReceiveNotification_RemovesFromQueue()
        {
            _service.SendNotification("TestEntity_Remove", "1", EntityOperation.CREATE);

            // Drain everything
            var all = DrainAll();
            Assert.Contains(all, n => n.EntityType == "TestEntity_Remove");

            // Queue should be empty now - our notification was consumed
            var afterDrain = _service.ReceiveNotification();
            Assert.Null(afterDrain);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            var exception = Record.Exception(() => _service.MarkAsRead(1));
            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_Update_GeneratesUpdateMessage()
        {
            _service.SendNotification("TestEntity_Update", "100", "Biology", EntityOperation.UPDATE);

            var all = DrainAll();
            var notification = all.Find(n => n.EntityType == "TestEntity_Update");
            Assert.NotNull(notification);
            Assert.Contains("updated", notification.Message);
            Assert.Contains("Biology", notification.Message);
        }

        [Fact]
        public void SendNotification_Create_GeneratesCreateMessage()
        {
            _service.SendNotification("TestEntity_Create", "3", "Jane Smith", EntityOperation.CREATE);

            var all = DrainAll();
            var notification = all.Find(n => n.EntityType == "TestEntity_Create");
            Assert.NotNull(notification);
            Assert.Contains("created", notification.Message);
            Assert.Contains("Jane Smith", notification.Message);
        }

        [Fact]
        public void SendNotification_OverloadWithoutDisplayName_Works()
        {
            _service.SendNotification("TestEntity_Overload", "5", EntityOperation.DELETE);

            var all = DrainAll();
            var notification = all.Find(n => n.EntityType == "TestEntity_Overload");
            Assert.NotNull(notification);
            Assert.Equal("DELETE", notification.Operation);
        }
    }
}

